eq2 = Eq((x + 1)**2 + y**2 + z**2, 49)
eq3 = Eq(x**2 + (y - 1)**2 + z**2, 64)
eq4 = Eq(x**2 + (y + 1)**2 + z**2, 81)

# Solve the system of equations
solution = solve((eq1, eq2, eq3, eq4), (x, y, z))
print(solution)
